function populateSupplierQuotations(frm) {
    console.log("Executing populateSupplierQuotations");

    frm.clear_table('supplier_criteria'); // Clear existing entries

    if (frm.doc.sub_rfq_number) {
        console.log("Filtering by custom_subrfq:", frm.doc.sub_rfq_number);

        frappe.db.get_list('Supplier Quotation', {
            fields: ['name', 'custom_subrfq', 'supplier'],
            filters: {
                custom_subrfq: frm.doc.sub_rfq_number,
            },
            limit: 2000
        }).then(quotations => {
            console.log("Fetched Quotations:", quotations);

            quotations.forEach(quotation => {
                let row = frm.add_child('supplier_criteria');
                row.supplier = quotation.supplier;

            });

            frm.refresh_field('supplier_criteria'); // Refresh table
        });
    }
}




