function getWinnerSupplier(frm) {
    console.log("Calculating winner supplier...");

    if (!frm.doc.supplier_criteria || frm.doc.supplier_criteria.length === 0) {
        frappe.msgprint(__('No supplier criteria data found!'));
        return;
    }

    let supplierQuotes = {};  // Store supplier price quotes
    let supplierScores = [];  // Store supplier rankings

    // Step 1: Get supplier list
    let supplierList = frm.doc.supplier_criteria.map(s => s.supplier);

    frappe.db.get_list('Supplier Quotation', {
        fields: ['name', 'supplier'],
        filters: { supplier: ['in', supplierList] }
    }).then(quotations => {
        if (quotations.length === 0) {
            frappe.msgprint(__('No supplier quotations found!'));
            return;
        }

        let quotationMap = Object.fromEntries(quotations.map(q => [q.supplier, q.name]));

        // Step 2: Fetch quoted prices
        frappe.db.get_list('Supplier Quotation Item', {
            fields: ['parent', 'rate'],
            filters: { parent: ['in', quotations.map(q => q.name)] }
        }).then(items => {
            items.forEach(item => {
                let supplier = Object.keys(quotationMap).find(s => quotationMap[s] === item.parent);
                if (!supplierQuotes[supplier] || item.rate < supplierQuotes[supplier]) {
                    supplierQuotes[supplier] = item.rate;
                }
            });

            console.log("Supplier Quotes:", supplierQuotes);

            // Step 3: Calculate Scores
            let maxScore = 0;
            let winnerSupplier = null;

            frm.doc.supplier_criteria.forEach(supplier => {
                let quotedPrice = supplierQuotes[supplier.supplier] || 0;

                let score = 
                    (quotedPrice * 0.30) + 
                    (supplier.document_readiness * 0.60) + 
                    (supplier.delivery_time * 0.10);

                supplierScores.push({
                    supplier: supplier.supplier,
                    score: score
                });

                if (score > maxScore) {
                    maxScore = score;
                    winnerSupplier = supplier.supplier;
                }
            });

            // Normalize Scores
            let totalScore = supplierScores.reduce((sum, s) => sum + s.score, 0);
            supplierScores.forEach(s => s.percentage = ((s.score / totalScore) * 100).toFixed(2));

            // Sort suppliers by rank
            supplierScores.sort((a, b) => b.score - a.score);

            // Assign ranking positions
            supplierScores.forEach((s, index) => {
                s.rank = index + 1;
            });

            console.log("Ranked Suppliers:", supplierScores);

            if (!winnerSupplier) {
                frappe.msgprint(__('No winner supplier determined.'));
                return;
            }


            console.log(`Winner Supplier: ${winnerSupplier}`);

            frm.clear_table('winner_rank');

            supplierScores.forEach(s => {
                let row = frm.add_child('winner_rank');
                row.supplier = s.supplier;
                row.rank = s.rank;
                row.score = s.score;
                row.percentage = s.percentage;
            });

            frm.refresh_field('winner_rank');

            // Step 5: Fetch Winner's Quotation Items
            let winnerQuotation = quotationMap[winnerSupplier];
            console.log(`Winner Quotation: ${winnerQuotation}`);


            frappe.model.with_doc('Supplier Quotation', winnerQuotation, function() {
                let quotationDoc = frappe.model.get_doc('Supplier Quotation', winnerQuotation);

                if (!quotationDoc || !quotationDoc.items) {
                    console.error("No items found for the winner quotation.");
                    return;
                }

                console.log("Winner Quotation Items:", quotationDoc.items);

                frm.clear_table('items');

                $.each(quotationDoc.items, function(index, item) {
                    let row = frm.add_child('items');
                    row.item_code = item.item_code;
                    row.description = item.description;
                    row.qty = item.qty;
                    row.uom-item.uom;
                    row.rate = item.rate;
                    row.amount = item.qty * item.rate;
                });

                frm.refresh_field('items');

                // Step 6: Set Winner Supplier

                frm.set_value('winner_supplier', winnerSupplier);
                frm.set_value('supplier_quotation',winnerQuotation );
                frm.refresh_field('winner_supplier');
                frm.refresh_field('supplier_quotation');


            });

        });
    });
}
